import java.util.Scanner;
public class CountEvenOddArray { public static void main(String[] args){Scanner s=new Scanner(System.in);System.out.print("Enter array size (1-100): ");if(!s.hasNextInt()){System.out.println("Enter a size from 1 to 100.");return;}int n=s.nextInt();if(n<1||n>100){System.out.println("Array size must be from 1 to 100.");return;}int even=0,odd=0;for(int i=0;i<n;i++){if(!s.hasNextInt()){System.out.println("Enter exactly "+n+" whole numbers.");return;}if(s.nextInt()%2==0)even++;else odd++;}if(s.hasNext()){System.out.println("Enter only the array values.");return;}System.out.println("Even count: "+even);System.out.println("Odd count: "+odd);}}
